"""Closes a window that has an AppTitle close prompt, and checks that the answer to the prompt decides what happens.

  close_prompt.py <blitzcc> <close_prompt.bb> <work directory>

Needs a display (xvfb-run is fine). The program writes to the debug log, because Print would go to the window. The prompt is answered with BLITZ_DIALOG_ANSWER, 0 being OK and 1 being Cancel.
"""
import os
import signal
import subprocess
import sys

blitzcc, source, work = sys.argv[1:4]
os.makedirs(work, exist_ok=True)
exe = os.path.join(work, "close_prompt" + (".exe" if os.name == "nt" else ""))
# BLITZCC_OPTIONS (for example "-d") adds options to the compiler, so that the test runs in Debug as well.
subprocess.run([blitzcc] + os.environ.get("BLITZCC_OPTIONS", "").split() + [source, "-o", exe], check=True)


def close(answer):
    env = dict(os.environ, BLITZ_DIALOG_ANSWER=str(answer))
    env.pop("BLITZ_HEADLESS", None)
    process = subprocess.Popen([exe], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=env)
    if process.stdout.readline().strip() != "started":
        process.kill()
        sys.exit("the program did not start")
    process.send_signal(signal.SIGTERM)  # SDL turns this into the same event as the close button of the window.
    out, _ = process.communicate(timeout=30)
    return process.returncode, out


code, out = close(0)
if "survived" in out or code != 0 or "Really quit?" not in out:
    sys.exit("OK on the prompt should end the program: code %s, output %r" % (code, out))
code, out = close(1)
if "survived" not in out or code != 0 or "Really quit?" not in out:
    sys.exit("Cancel on the prompt should keep the program running: code %s, output %r" % (code, out))
print("close prompt ok")
